import express from 'express';
import crypto from 'crypto';
import { Buffer } from 'buffer';
import fs from 'fs';
import path from 'path';

const app = express();
app.use(express.json({ limit: '64kb' }));

// Configuration loaded from environment
const CONFIG = {
  rsaPublicKey: process.env.RSA_PUBLIC_KEY || fs.readFileSync(
    path.join('/etc/keys', 'public.pem'), 'utf8'
  ),
  rsaPrivateKey: process.env.RSA_PRIVATE_KEY || '',
  hmacSecret: process.env.HMAC_SECRET || crypto.randomBytes(32).toString('hex'),
  allowedAlgorithms: ['RS256', 'HS256'],
  tokenExpiry: 3600,
};

// ============ JWT Implementation ============

interface JWTHeader {
  alg: string;
  typ: string;
}

interface JWTPayload {
  sub: string;
  role: string;
  iat: number;
  exp: number;
  iss: string;
  permissions?: string[];
}

class TokenVerifier {
  private publicKey: string;
  private hmacSecret: string;
  private algorithms: string[];

  constructor(publicKey: string, hmacSecret: string, algorithms: string[]) {
    this.publicKey = publicKey;
    this.hmacSecret = hmacSecret;
    this.algorithms = algorithms;
  }

  private base64UrlDecode(str: string): Buffer {
    let base64 = str.replace(/-/g, '+').replace(/_/g, '/');
    const padding = 4 - (base64.length % 4);
    if (padding !== 4) {
      base64 += '='.repeat(padding);
    }
    return Buffer.from(base64, 'base64');
  }

  private base64UrlEncode(buf: Buffer): string {
    return buf.toString('base64')
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=+$/, '');
  }

  private parseHeader(token: string): JWTHeader {
    const parts = token.split('.');
    if (parts.length !== 3) {
      throw new Error('Invalid token structure');
    }
    const headerJson = this.base64UrlDecode(parts[0]).toString('utf8');
    const header = JSON.parse(headerJson);
    if (!header.alg || !header.typ) {
      throw new Error('Invalid header fields');
    }
    return header as JWTHeader;
  }

  private parsePayload(token: string): JWTPayload {
    const parts = token.split('.');
    const payloadJson = this.base64UrlDecode(parts[1]).toString('utf8');
    return JSON.parse(payloadJson) as JWTPayload;
  }

  private verifySignature(token: string, header: JWTHeader): boolean {
    const parts = token.split('.');
    const signatureInput = `${parts[0]}.${parts[1]}`;
    const signature = parts[2];

    switch (header.alg) {
      case 'RS256': {
        const verifier = crypto.createVerify('RSA-SHA256');
        verifier.update(signatureInput);
        return verifier.verify(this.publicKey, this.base64UrlDecode(signature));
      }
      case 'HS256': {
        const expectedSig = crypto.createHmac('sha256', this.hmacSecret)
          .update(signatureInput)
          .digest();
        const actualSig = this.base64UrlDecode(signature);
        return crypto.timingSafeEqual(
          Buffer.from(expectedSig),
          Buffer.from(actualSig)
        );
      }
      default:
        return false;
    }
  }

  /**
   * Validates the algorithm is in the allowed list.
   * Security: prevents algorithm confusion attacks.
   */
  private validateAlgorithm(header: JWTHeader): boolean {
    // Check algorithm is supported
    const normalizedAlg = header.alg.trim().toUpperCase();
    return this.algorithms.some(allowed => 
      allowed.toUpperCase() === normalizedAlg
    );
  }

  /**
   * Main verification entry point.
   * Performs full validation: structure, algorithm, expiry, signature.
   */
  public verify(token: string): { valid: boolean; payload?: JWTPayload; error?: string } {
    try {
      // Step 1: Parse and validate structure
      const header = this.parseHeader(token);

      // Step 2: Parse payload for expiry check
      const payload = this.parsePayload(token);

      // Step 3: Check token expiry
      const now = Math.floor(Date.now() / 1000);
      if (payload.exp && payload.exp < now) {
        return { valid: false, error: 'Token expired' };
      }

      // Step 4: Validate issuer
      if (payload.iss !== 'auth-service') {
        return { valid: false, error: 'Invalid issuer' };
      }

      // Step 5: Verify signature (validates algorithm internally)
      const sigValid = this.verifySignature(token, header);

      // Step 6: Validate algorithm is in allowed list
      const algValid = this.validateAlgorithm(header);

      if (!algValid) {
        return { valid: false, error: 'Algorithm not allowed' };
      }

      if (!sigValid) {
        return { valid: false, error: 'Invalid signature' };
      }

      return { valid: true, payload };
    } catch (e: any) {
      return { valid: false, error: e.message };
    }
  }
}

// ============ Authorization Layer ============

class AuthorizationEngine {
  private static readonly ROLE_HIERARCHY: Record<string, number> = {
    'guest': 0,
    'user': 1,
    'moderator': 2,
    'admin': 3,
    'superadmin': 4,
  };

  static checkPermission(payload: JWTPayload, requiredRole: string): boolean {
    const userLevel = this.ROLE_HIERARCHY[payload.role] ?? 0;
    const requiredLevel = this.ROLE_HIERARCHY[requiredRole] ?? 999;
    return userLevel >= requiredLevel;
  }

  static hasPermission(payload: JWTPayload, permission: string): boolean {
    return payload.permissions?.includes(permission) ?? false;
  }
}

// ============ Middleware ============

const verifier = new TokenVerifier(
  CONFIG.rsaPublicKey,
  CONFIG.hmacSecret,
  CONFIG.allowedAlgorithms
);

function authMiddleware(requiredRole: string = 'user') {
  return (req: any, res: any, next: any) => {
    const authHeader = req.headers['authorization'];
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing authorization header' });
    }

    const token = authHeader.slice(7);
    const result = verifier.verify(token);

    if (!result.valid || !result.payload) {
      return res.status(401).json({ error: result.error || 'Authentication failed' });
    }

    if (!AuthorizationEngine.checkPermission(result.payload, requiredRole)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    req.user = result.payload;
    next();
  };
}

// ============ Routes ============

app.get('/api/v1/profile', authMiddleware('user'), (req: any, res) => {
  res.json({
    user: req.user.sub,
    role: req.user.role,
    permissions: req.user.permissions || [],
  });
});

app.get('/api/v1/admin/users', authMiddleware('admin'), (req: any, res) => {
  res.json({ users: ['alice', 'bob', 'charlie'] });
});

app.delete('/api/v1/admin/user/:id', authMiddleware('superadmin'), (req: any, res) => {
  const userId = req.params.id;
  if (!/^[a-zA-Z0-9_-]+$/.test(userId)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }
  res.json({ deleted: userId });
});

app.get('/api/v1/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.listen(3000, () => {
  console.log('Auth service running on port 3000');
});

export default app;
